	 * @see https://www.chilkatsoft.com/refdoc/phpCkPdfRef.html#SignPdfBdAsync
	 * @param CkJsonObject $jsonOptions
	 * @param CkBinData $bd
	 * @return ?CkTask
	 */
	function SignPdfBdAsync($jsonOptions,$bd) {
		return chilkat::_obj(CkPdf_SignPdfBdAsync($this->_cPtr,$jsonOptions,$bd),'CkTask');
	}

	/**
	 * Updates or adds XMP metdata to a PDF.  The metadata is passed in ARG1. If successful, the PDF with updated or inserted metadata is written to ARG2.
	 * @see https://www.chilkatsoft.com/refdoc/phpCkPdfRef.html#UpdateMetadata
	 * @param CkStringBuilder $sb
	 * @param ?string $outFilePath
	 * @return bool
	 */
	function UpdateMetadata($sb,$outFilePath) {
		return CkPdf_UpdateMetadata($this->_cPtr,$sb,$outFilePath);
	}

	/**
	 * Updates or adds XMP metdata to a PDF.  The metadata is passed in ARG1. If successful, the PDF with updated or inserted metadata is written to ARG2.
	 * @see https://www.chilkatsoft.com/refdoc/phpCkPdfRef.html#UpdateMetadataBd
	 * @param CkStringBuilder $sb
	 * @param CkBinData $bd
	 * @return bool
	 */
	function UpdateMetadataBd($sb,$bd) {
		return CkPdf_UpdateMetadataBd($this->_cPtr,$sb,$bd);
	}

	/**
	 * Verifies the Nth signature contained in the PDF, where the 1st signature is indicated by an ARG1 of 0.  Returns _TRUE_ if the signature valid, otherwise returns _FALSE_.  The ARG2 is an output argument and is populated with information about the validated or unvalidated signature.
	 * @see https://www.chilkatsoft.com/refdoc/phpCkPdfRef.html#VerifySignature
	 * @param int $index
	 * @param CkJsonObject $sigInfo
	 * @return bool
	 */
	function VerifySignature($index,$sigInfo) {
		return CkPdf_VerifySignature($this->_cPtr,$index,$sigInfo);
	}
}
